// Some portions generated by Claude Code
package org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Map;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

public class JoinQueryEvaluationStepPreservesOrderTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static StatementPattern pattern(String s, String p, String o) {
		return new StatementPattern(Var.of(s), Var.of(p, VF.createIRI("ex:" + p)), Var.of(o));
	}

	@Test
	public void plainJoinOfStatementPatternsPreservesLeftArgOrder() {
		Join join = new Join(pattern("a", "p1", "b"), pattern("b", "p2", "c"));

		assertThat(JoinQueryEvaluationStep.preservesLeftArgOrder(join)).isTrue();
	}

	@Test
	public void joinWithServiceRightArgDoesNotPreserveLeftArgOrder() {
		Service service = new Service(Var.of("endpoint", VF.createIRI("ex:endpoint")), pattern("b", "p2", "c"), "",
				Map.of(), null, false);
		Join join = new Join(pattern("a", "p1", "b"), service);

		assertThat(JoinQueryEvaluationStep.preservesLeftArgOrder(join)).isFalse();
	}
}
